-- Part B: recurring conversation scenarios -> response guidance for the bot
INSERT INTO clinic_faqs (topic, question, answer, is_active)
VALUES
  ('Scenario', 'ลูกค้าทักมาแบบกว้างๆ ไม่ระบุบริการ (เช่น "สนใจค่ะ" "สอบถามโปรโมชั่น" "เริ่มต้น")', 'อย่าเพิ่งเสนอราคาหรือบริการใดบริการหนึ่งทันที ให้ถามคำถามเพื่อชวนลูกค้าระบุความต้องการก่อนเสมอ เช่น "คุณลูกค้าสนใจดูแลส่วนไหนดีคะ ผิวหน้า ปรับรูปหน้า หรือศัลยกรรมจมูก/ตาคะ" แล้วค่อยแนะนำโปรโมชั่นที่ตรงจุด', true),
  ('Scenario', 'ลูกค้าถามราคาโบท็อกซ์/ฟิลเลอร์โดยไม่ระบุยี่ห้อ', 'ราคาต่างกันมากตามยี่ห้อและปริมาณ ให้ถามก่อนว่าลูกค้าสนใจยี่ห้อไหนหรือมีงบประมาณเท่าไหร่ แล้วจึงแนะนำยี่ห้อ/ราคาที่เหมาะสม อย่าฟันธงราคาเดียวโดยไม่ถามรายละเอียดก่อน', true),
  ('Scenario', 'ลูกค้าไม่มั่นใจ/กลัวเจ็บ โดยเฉพาะการฉีดฟิลเลอร์ปากเป็นครั้งแรก', 'ให้เชิงรุกในการสร้างความมั่นใจก่อนที่ลูกค้าจะถาม เช่น อธิบายว่ามียาชาแบบทาและฉีดเฉพาะจุดให้ทุกครั้ง ไม่มีค่าใช้จ่ายเพิ่ม และระหว่างทำจะไม่ปวดมาก', true),
  ('Scenario', 'ลูกค้าต้องการผลลัพธ์เฉพาะเจาะจงจากเคสแก้ไข (เช่น "แก้จมูกให้เชิดพุ่ง" "อยากได้ทรงนี้")', 'ห้ามยืนยันผลลัพธ์ที่แน่นอนจากการดูรูปหรือคำบอกเล่าเพียงอย่างเดียว ให้แจ้งว่าเคสแก้ไขจำเป็นต้องให้คุณหมอประเมินสภาพเดิมหน้างานก่อนจึงจะให้คำตอบที่ชัดเจนได้ พร้อมชวนนัดปรึกษาฟรี', true),
  ('Scenario', 'ลูกค้าถามว่าคุณหมอคนไหนอยู่ปฏิบัติงานวันที่ต้องการ หรือขอคิวคุณหมอเฉพาะคน', 'ตารางคุณหมอเปลี่ยนแปลงได้ทุกสัปดาห์ อย่าตอบตารางที่ไม่ได้ยืนยันสด ให้แจ้งว่าจะประสานตรวจสอบคิวให้และรอสักครู่ หรือส่งต่อให้แอดมิน/มนุษย์ยืนยันอีกครั้ง', true),
  ('Scenario', 'ลูกค้าต้องการส่วนลดเพิ่มเมื่อทำหลายหัตถการพร้อมกัน', 'แจ้งลูกค้าว่าสามารถนัดปรึกษาคุณหมอฟรีเพื่อออกแบบคอร์สและขอราคาพิเศษสำหรับแพ็กเกจรวมได้ อย่าคิดหรือยืนยันส่วนลดเองโดยไม่ผ่านการตรวจสอบ', true),
  ('Scenario', 'มีข้อความเข้ามาแบบไม่ใช่ลูกค้า (เช่น ชวนร่วมพาร์ทเนอร์ธุรกิจ ขอรีวิว/collab จากอินฟลูเอนเซอร์ ขายของ B2B)', 'ไม่ใช่คำถามบริการลูกค้า บอทควรตอบทักทายสั้นๆ อย่างสุภาพและแจ้งว่าจะส่งต่อให้ทีมที่เกี่ยวข้องติดต่อกลับ ไม่ต้องพยายามเสนอขายบริการคลินิกให้กับข้อความประเภทนี้', true),
  ('Scenario', 'ลูกค้าถามปัญหาที่นอกเหนือขอบเขตบริการของคลินิก (เช่น ก้อนไขมันที่หนังตา ปัญหาผิวที่อาจเป็นโรคเฉพาะทาง)', 'หากไม่แน่ใจว่าคลินิกให้บริการหรือไม่ ให้ปรึกษาก่อนว่าเข้าข่ายบริการของคลินิกหรือควรแนะนำให้ไปพบแพทย์เฉพาะทางอื่น (เช่น จักษุแพทย์) แทนที่จะรับปากทำหัตถการที่ไม่ถนัด', true),
  ('Scenario', 'ลูกค้าให้เบอร์โทรศัพท์ในแชทเพื่อขอให้โทรกลับ หรือขอคุยกับเจ้าหน้าที่โดยตรง', 'เป็นจุดที่ควรส่งต่อให้เจ้าหน้าที่มนุษย์ติดต่อกลับ (handoff) แจ้งลูกค้าว่าจะรีบประสานงานให้เจ้าหน้าที่ติดต่อกลับโดยเร็ว', true),
  ('Scenario', 'ข้อความโปรโมชั่นระบุ "เหลือสิทธิ์จำกัด" หรือ "เหลือ X เคสสุดท้าย"', 'ข้อความนี้เป็นสำนวนการตลาดที่ใช้ซ้ำในหลายแคมเปญ ไม่ใช่จำนวนคงเหลือจริงแบบเรียลไทม์ บอทไม่ควรยืนยันจำนวนสิทธิ์ที่เหลือจริงหากไม่มีข้อมูลสต็อกที่อัปเดตจริง', true),
  ('Scenario', 'ลูกค้าถามเป็นภาษาอังกฤษเกี่ยวกับราคา ที่ตั้ง หรือบริการแก้ไข', 'ควรตอบเป็นภาษาอังกฤษกลับให้ลูกค้าเข้าใจง่าย โดยใช้ข้อมูลราคา/ที่ตั้ง/เงื่อนไขเดียวกับที่ตอบลูกค้าไทย', true);
